body.tc-body {
  font-family: "Jost Compact J", sans-serif;
}
body.tc-body .tc-story-river .tc-tiddler-frame {
  background: #fff;
  color: #151515;
  border: 1px solid #dadada;
  border-radius: 0;
  box-shadow: none;
}
body.tc-body .tc-tiddler-frame .tc-titlebar .tc-title,
body.tc-body .tc-tiddler-frame .tc-tiddler-body,
body.tc-body .tc-tiddler-frame .tc-tiddler-body table {
  font-family: "Jost Compact J", sans-serif;
}
.tc-story-river .tc-titlebar .tc-title {
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .025em;
  line-height: 1.12;
}
.tc-story-river .tc-tiddler-body {
  font-weight: 400;
  line-height: 1.4;
}
.tc-story-river .tc-tiddler-body > p {
  margin: 0 0 .6em;
}
.tc-story-river .tc-tiddler-body :is(h1,h2,h3,h4,h5,h6) {
  color: #111;
  font-family: "Jost Compact J", sans-serif;
  font-weight: 700;
  line-height: 1.15;
  margin: 1em 0 .35em;
  break-after: avoid;
}
.tc-story-river .tc-tiddler-body :is(h1,h2) {
  text-transform: uppercase;
  letter-spacing: .025em;
}
.tc-story-river .tc-tiddler-body h1 { font-size: 1.5em; }
.tc-story-river .tc-tiddler-body h2 { font-size: 1.22em; }
.tc-story-river .tc-tiddler-body h3 { font-size: 1.1em; }
.tc-story-river .tc-tiddler-body :is(h4,h5,h6) { font-size: 1em; }
.tc-story-river .tc-tiddler-frame .tc-tiddler-body a.tc-tiddlylink,
.tc-story-river .tc-tiddler-frame .tc-tiddler-body a.tc-tiddlylink-external {
  color: inherit;
  text-decoration: underline;
  text-underline-offset: .12em;
}
.tc-story-river .tc-tiddler-body table {
  font-weight: 400;
  border-collapse: collapse;
  border-spacing: 0;
  border: 0;
}

.tc-story-river .tc-tiddler-body table > :is(thead, tbody, tfoot) > tr,
.tc-story-river .tc-tiddler-body table > :is(thead, tbody, tfoot) > tr > :is(td, th) {
  border: 0;
}

.tc-story-river .tc-tiddler-body table > :is(thead, tbody, tfoot) > tr > :is(td, th) {
  padding: 0.2em 0.55em;
  background: #fff;
  color: #111;
}

.tc-story-river .tc-tiddler-body table > tbody > tr:is(
  :nth-child(6n+1 of tr:has(> td)),
  :nth-child(6n+2 of tr:has(> td)),
  :nth-child(6n+3 of tr:has(> td))
) > td {
  background: #dedede;
}

.tc-story-river .tc-tiddler-body table > :is(thead, tbody, tfoot) > tr > th,
.tc-story-river .tc-tiddler-body table > thead > tr > td {
  font-weight: 700;
  color: #000;
  background: #fff;
}

.tc-story-river .tc-tiddler-body table > :is(thead, tbody, tfoot) > tr > th a,
.tc-story-river .tc-tiddler-body table > thead > tr > td a {
  color: inherit;
}

\rules only html
<$list filter="[[$:/config/JostHandbook/Columns]get[text]match[2]]">
.tc-story-river .tc-tiddler-frame .tc-tiddler-body {
  column-count: 2;
  column-gap: 2em;
}
.tc-story-river .tc-tiddler-body > :is(table,pre,figure) { column-span: all; }
</$list>
